import React, { useState } from "react";
import axios from "axios";
import { useLanguage } from "../contexts/LanguageContext";
import LanguageToggle from "./LanguageToggle";

const ImageUpload = () => {
  const { t, language } = useLanguage();
  const [selectedImage, setSelectedImage] = useState(null);
  const [previewUrl, setPreviewUrl] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [result, setResult] = useState(null);

  // Handle file selection
  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setSelectedImage(file);
      setPreviewUrl(URL.createObjectURL(file));
      setError(null);
      setResult(null);
    }
  };

  // Handle camera capture
  const handleCameraCapture = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      const video = document.createElement("video");
      video.srcObject = stream;
      video.play();

      // Take a snapshot after a short delay
      setTimeout(() => {
        const canvas = document.createElement("canvas");
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        canvas.getContext("2d").drawImage(video, 0, 0);

        // Convert to blob
        canvas.toBlob((blob) => {
          const file = new File([blob], "camera-capture.jpg", { type: "image/jpeg" });
          setSelectedImage(file);
          setPreviewUrl(URL.createObjectURL(blob));
          setError(null);
          setResult(null);

          // Stop the camera stream
          stream.getTracks().forEach(track => track.stop());
        }, "image/jpeg");
      }, 500);
    } catch (err) {
      setError("Failed to access camera: " + err.message);
    }
  };

  // Handle image upload and analysis
  const handleAnalyze = async () => {
    if (!selectedImage) {
      setError("Please select or capture an image first");
      return;
    }

    setLoading(true);
    setError(null);

    try {
      // Convert image to base64
      const reader = new FileReader();
      reader.readAsDataURL(selectedImage);
      reader.onloadend = async () => {
        const base64data = reader.result;

        // Send to backend for analysis
        const response = await axios.post("/predict", {
          image: base64data,
          lang: language
        });

        setResult(response.data);
        setLoading(false);
      };
    } catch (err) {
      setError("Error analyzing image: " + err.message);
      setLoading(false);
    }
  };

  return (
    <div className="card fade-in">
      <LanguageToggle />
      <h1>{t("title")}</h1>

      <div>
        <input
          type="file"
          accept="image/*"
          onChange={handleImageChange}
          style={{ display: "none" }}
          id="image-upload"
        />
        <label htmlFor="image-upload">
          <button as="span">{t("uploadButton")}</button>
        </label>

        <button onClick={handleCameraCapture} style={{ marginLeft: "10px" }}>
          {t("captureButton")}
        </button>
      </div>

      {previewUrl && (
        <div className="preview-container">
          <img src={previewUrl} alt="Preview" className="image-preview" />
          <button onClick={handleAnalyze} disabled={loading}>
            {loading ? t("loading") : t("analyzeButton")}
          </button>
        </div>
      )}

      {error && <p className="error">{error}</p>}
    </div>
  );
};

export default ImageUpload;
